import { screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import type { ApiClient } from '@/lib/api/client';
import type { components } from '@/lib/api/schema';
import { failure, groupsApi, konferenca, poroka, signedIn, skupno } from '@/test/groupsApi';
import { renderApp } from '@/test/renderApp';

type Member = components['schemas']['Member'];

const ana: Member = { userId: 'u-ana', name: 'Ana Novak', email: 'ana.novak@example.com', role: 'OWNER' };
const marko: Member = { userId: 'u-marko', name: 'Marko Pirc', email: 'marko@example.com', role: 'EDITOR' };
const petra: Member = { userId: 'u-petra', name: 'Petra Kos', email: 'petra@example.com', role: 'VIEWER' };

/** The groups stand-in with the members of group g-1 and the refusals the server may give. */
function membersApi(members: Member[], refuse?: { status: number; code: 'LAST_OWNER' | 'NOT_FOUND' }) {
  const { api: groups, calls } = groupsApi([konferenca, poroka, skupno]);
  const list = members.map((m) => ({ ...m }));
  const api: ApiClient = {
    ...groups,
    request: (async (method: string, path: string, body?: { role: Member['role'] }) => {
      const base = '/groups/g-1/members';
      const one = /^\/groups\/g-1\/members\/(.+)$/.exec(path);
      if (path === base || one || path === '/groups/g-1/leave' || path === '/groups/g-1/invitations') {
        calls.push(`${method} ${path} ${body ? JSON.stringify(body) : ''}`.trim());
      }
      if (path === '/groups/g-1/invitations') return [];
      if (path === base) return list.map((m) => ({ ...m }));
      if (one && method !== 'GET' && refuse) throw failure(refuse.status, refuse.code);
      if (path === '/groups/g-1/leave' && refuse) throw failure(refuse.status, refuse.code);
      if (one && method === 'PUT') {
        const member = list.find((m) => m.userId === one[1]);
        if (member && body) member.role = body.role;
        return member;
      }
      if (one && method === 'DELETE') {
        list.splice(
          list.findIndex((m) => m.userId === one[1]),
          1,
        );
        return undefined;
      }
      if (path === '/groups/g-1/leave') return undefined;
      return groups.request(method, path, body);
    }) as ApiClient['request'],
  };
  return { api, calls };
}

describe('the member list of the Members tab (R-004-01, R-004-02, R-004-04, R-004-06, R-004-07)', () => {
  it('lists every member with name, e-mail and role and gives an Owner the controls', async () => {
    const { api } = membersApi([ana, marko, petra]);
    renderApp('/groups/g-1/members', { auth: signedIn(), api });
    const row = await screen.findByRole('row', { name: /Marko Pirc/ });
    expect(within(row).getByText('marko@example.com')).toBeInTheDocument();
    expect(within(row).getByRole('combobox', { name: 'Role of Marko Pirc' })).toHaveValue('EDITOR');
    expect(within(row).getByRole('button', { name: 'Remove' })).toBeInTheDocument();
    const own = screen.getByRole('row', { name: /Ana Novak/ });
    expect(within(own).getByRole('button', { name: 'Leave group' })).toBeInTheDocument();
    expect(within(own).queryByRole('button', { name: 'Remove' })).not.toBeInTheDocument();
  });

  it('shows an Editor or Viewer the list without role selects and without Remove', async () => {
    const { api, calls } = membersApi([ana, marko, petra]);
    renderApp('/groups/g-2/members', { auth: signedIn(), api });
    await screen.findByRole('heading', { name: 'Poroka' });
    expect(calls.some((c) => c.includes('/groups/g-2/invitations'))).toBe(false);
    expect(screen.queryByRole('button', { name: 'Remove' })).not.toBeInTheDocument();
    expect(screen.queryByRole('combobox', { name: /Role of/ })).not.toBeInTheDocument();
  });

  it('changes a role with the select and sends it to the server', async () => {
    const { api, calls } = membersApi([ana, marko]);
    renderApp('/groups/g-1/members', { auth: signedIn(), api });
    const select = await screen.findByRole('combobox', { name: 'Role of Marko Pirc' });
    await userEvent.selectOptions(select, 'VIEWER');
    expect(calls).toContain('PUT /groups/g-1/members/u-marko {"role":"VIEWER"}');
    expect(await screen.findByRole('combobox', { name: 'Role of Marko Pirc' })).toHaveValue('VIEWER');
  });

  it('removes a member only after the confirmation', async () => {
    const { api, calls } = membersApi([ana, marko]);
    renderApp('/groups/g-1/members', { auth: signedIn(), api });
    const row = await screen.findByRole('row', { name: /Marko Pirc/ });
    await userEvent.click(within(row).getByRole('button', { name: 'Remove' }));
    const dialog = await screen.findByRole('dialog', { name: 'Remove member' });
    expect(calls.some((c) => c.startsWith('DELETE'))).toBe(false);
    await userEvent.click(within(dialog).getByRole('button', { name: 'Remove' }));
    await screen.findByText('Ana Novak');
    expect(screen.queryByText('Marko Pirc')).not.toBeInTheDocument();
    expect(calls).toContain('DELETE /groups/g-1/members/u-marko');
  });

  it('cancelling the confirmation removes nobody', async () => {
    const { api, calls } = membersApi([ana, marko]);
    renderApp('/groups/g-1/members', { auth: signedIn(), api });
    const row = await screen.findByRole('row', { name: /Marko Pirc/ });
    await userEvent.click(within(row).getByRole('button', { name: 'Remove' }));
    await userEvent.click(within(await screen.findByRole('dialog')).getByRole('button', { name: 'Cancel' }));
    expect(calls.some((c) => c.startsWith('DELETE'))).toBe(false);
  });

  it('leaving the group goes to the group list', async () => {
    const { api, calls } = membersApi([ana, marko]);
    renderApp('/groups/g-1/members', { auth: signedIn(), api });
    await userEvent.click(await screen.findByRole('button', { name: 'Leave group' }));
    await userEvent.click(
      within(await screen.findByRole('dialog')).getByRole('button', { name: 'Leave group' }),
    );
    await screen.findByRole('heading', { name: 'Groups' });
    expect(calls).toContain('POST /groups/g-1/leave');
  });

  it('shows the last-Owner message and keeps the Owner when leaving is refused', async () => {
    const { api } = membersApi([ana, marko], { status: 409, code: 'LAST_OWNER' });
    renderApp('/groups/g-1/members', { auth: signedIn(), api });
    await userEvent.click(await screen.findByRole('button', { name: 'Leave group' }));
    await userEvent.click(
      within(await screen.findByRole('dialog')).getByRole('button', { name: 'Leave group' }),
    );
    expect(
      await screen.findByText('A group needs at least one Owner. Make another member an Owner first.'),
    ).toBeInTheDocument();
    expect(within(screen.getByRole('row', { name: /Ana Novak/ })).getByText('Owner')).toBeInTheDocument();
  });

  it('shows the group list when the server says the group is gone (EX-004-03)', async () => {
    const { api } = membersApi([ana, marko], { status: 404, code: 'NOT_FOUND' });
    renderApp('/groups/g-1/members', { auth: signedIn(), api });
    const row = await screen.findByRole('row', { name: /Marko Pirc/ });
    await userEvent.click(within(row).getByRole('button', { name: 'Remove' }));
    await userEvent.click(within(await screen.findByRole('dialog')).getByRole('button', { name: 'Remove' }));
    await screen.findByRole('heading', { name: 'Groups' });
  });
});

src/features/groups/group-trash.test.tsx.source:
import { screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import type { ApiClient } from '@/lib/api/client';
import type { components } from '@/lib/api/schema';
import { renderApp } from '@/test/renderApp';
import { failure, groupsApi, konferenca, poroka, signedIn } from '@/test/groupsApi';

type DeletedGroup = components['schemas']['DeletedGroup'];

/** The groups stand-in plus the delete, restore and Deleted groups calls of US-015. */
function trashApi(initial = [konferenca, poroka], options: { restoreFails?: boolean } = {}) {
  const base = groupsApi(initial);
  const deleted: DeletedGroup[] = [];
  const calls: string[] = [];
  const api: ApiClient = {
    ...base.api,
    request: (async (method: string, path: string, body?: { name?: string }) => {
      const trash = /^\/groups\/([^/]+)\/trash$/.exec(path);
      const restore = /^\/groups\/([^/]+)\/restore$/.exec(path);
      if (trash && method === 'POST') {
        calls.push(`POST ${path} ${JSON.stringify(body)}`);
        const index = base.groups.findIndex((g) => g.id === trash[1]);
        const group = base.groups[index]!;
        if (body?.name !== group.name) {
          throw Object.assign(failure(400, 'VALIDATION_FAILED'), {
            body: {
              status: 400,
              code: 'VALIDATION_FAILED',
              message: 'x',
              errors: [{ field: 'name', code: 'NAME_MISMATCH', message: 'x' }],
            },
          });
        }
        base.groups.splice(index, 1);
        deleted.push({ id: group.id, name: group.name, trashedAt: '2026-11-01T10:00:00Z', daysLeft: 30 });
        return undefined;
      }
      if (restore && method === 'POST') {
        calls.push(`POST ${path}`);
        if (options.restoreFails) throw failure(409, 'GROUP_NAME_TAKEN');
        const index = deleted.findIndex((g) => g.id === restore[1]);
        base.groups.push({ id: deleted[index]!.id, name: deleted[index]!.name, role: 'OWNER' });
        deleted.splice(index, 1);
        return undefined;
      }
      if (path === '/deleted-groups') return deleted.map((g) => ({ ...g }));
      return base.api.request(method as 'GET', path as '/groups', body as never);
    }) as ApiClient['request'],
  };
  return { api, calls };
}

describe('delete group dialog (R-015-01, R-015-02, R-015-07, AC-015-01, AC-015-02)', () => {
  async function openDelete() {
    const row = (await screen.findByRole('link', { name: 'Konferenca 2026' })).closest('tr') as HTMLElement;
    await userEvent.click(within(row).getByRole('button', { name: 'Delete group' }));
    return screen.getByRole('dialog', { name: 'Delete group' });
  }

  it('offers Delete group to an Owner only', async () => {
    const { api } = trashApi();
    renderApp('/', { auth: signedIn(), api });
    await screen.findByRole('link', { name: 'Konferenca 2026' });
    expect(screen.getAllByRole('button', { name: 'Delete group' })).toHaveLength(1);
  });

  it('deletes the group when the exact name is typed and removes it from the list', async () => {
    const { api, calls } = trashApi();
    renderApp('/', { auth: signedIn(), api });
    const dialog = await openDelete();
    await userEvent.type(within(dialog).getByLabelText(/^Type the group name to confirm/), 'Konferenca 2026');
    await userEvent.click(within(dialog).getByRole('button', { name: 'Delete group' }));
    await screen.findByRole('link', { name: 'Poroka' });
    expect(screen.queryByRole('link', { name: 'Konferenca 2026' })).toBeNull();
    expect(calls).toEqual(['POST /groups/g-1/trash {"name":"Konferenca 2026"}']);
    expect(screen.queryByRole('dialog')).toBeNull();
  });

  it('keeps the dialog open and the typed text when the name differs in case', async () => {
    const { api } = trashApi();
    renderApp('/', { auth: signedIn(), api });
    const dialog = await openDelete();
    const input = within(dialog).getByLabelText(/^Type the group name to confirm/);
    await userEvent.type(input, 'konferenca 2026');
    await userEvent.click(within(dialog).getByRole('button', { name: 'Delete group' }));
    expect(await within(dialog).findByRole('alert')).toHaveTextContent('does not match');
    expect(input).toHaveValue('konferenca 2026');
    expect(screen.getByRole('link', { name: 'Konferenca 2026', hidden: true })).toBeInTheDocument();
  });

  it('closes without deleting on Cancel', async () => {
    const { api, calls } = trashApi();
    renderApp('/', { auth: signedIn(), api });
    const dialog = await openDelete();
    await userEvent.click(within(dialog).getByRole('button', { name: 'Cancel' }));
    expect(screen.queryByRole('dialog')).toBeNull();
    expect(calls).toEqual([]);
  });
});

describe('Deleted groups (R-015-04, R-015-05, R-015-10, AC-015-08)', () => {
  const trashed: DeletedGroup = {
    id: 'g-9',
    name: 'Stara skupina',
    trashedAt: '2026-11-01T10:00:00Z',
    daysLeft: 18,
  };

  function withDeleted(options: { restoreFails?: boolean } = {}) {
    const stand = trashApi([konferenca], options);
    const inner = stand.api.request;
    let listed = [trashed];
    const api: ApiClient = {
      ...stand.api,
      request: (async (method: string, path: string, body?: unknown) => {
        if (path === '/deleted-groups') return listed.map((g) => ({ ...g }));
        if (path === '/groups/g-9/restore') {
          stand.calls.push('POST /groups/g-9/restore');
          if (options.restoreFails) throw failure(409, 'GROUP_NAME_TAKEN');
          listed = [];
          return undefined;
        }
        return inner(method as 'GET', path as '/groups', body as never);
      }) as ApiClient['request'],
    };
    return { api, calls: stand.calls };
  }

  it('lists each group in Trash with the days left', async () => {
    const { api } = withDeleted();
    renderApp('/deleted-groups', { auth: signedIn(), api });
    const row = (await screen.findByText('Stara skupina')).closest('tr') as HTMLElement;
    expect(within(row).getByText('18')).toBeInTheDocument();
    expect(within(row).getByRole('button', { name: 'Restore' })).toBeInTheDocument();
  });

  it('shows an empty state when nothing is in Trash', async () => {
    const { api } = trashApi();
    renderApp('/deleted-groups', { auth: signedIn(), api });
    expect(await screen.findByText(/Groups you delete stay here for 30 days/)).toBeInTheDocument();
  });

  it('restores a group and says so', async () => {
    const { api, calls } = withDeleted();
    renderApp('/deleted-groups', { auth: signedIn(), api });
    await userEvent.click(await screen.findByRole('button', { name: 'Restore' }));
    expect(await screen.findByRole('status')).toHaveTextContent('The group was restored.');
    expect(calls).toContain('POST /groups/g-9/restore');
    expect(screen.queryByText('Stara skupina')).toBeNull();
  });

  it('explains a name clash and keeps the group in the list', async () => {
    const { api } = withDeleted({ restoreFails: true });
    renderApp('/deleted-groups', { auth: signedIn(), api });
    await userEvent.click(await screen.findByRole('button', { name: 'Restore' }));
    expect(await screen.findByRole('alert')).toHaveTextContent('Rename that group first');
    expect(screen.getByText('Stara skupina')).toBeInTheDocument();
  });

  it('shows an error with Try again when the list cannot be loaded', async () => {
    const { api } = trashApi();
    const broken: ApiClient = {
      ...api,
      request: (async (method: string, path: string) => {
        if (path === '/deleted-groups') throw failure(500, 'INTERNAL_ERROR');
        return api.request(method as 'GET', path as '/groups');
      }) as ApiClient['request'],
    };
    renderApp('/deleted-groups', { auth: signedIn(), api: broken });
    expect(await screen.findByRole('alert')).toHaveTextContent('Something went wrong');
    expect(screen.getByRole('button', { name: 'Try again' })).toBeInTheDocument();
  });
});

src/features/tags/manage-tags.test.tsx.source:
import { screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ApiError, type ApiClient } from '@/lib/api/client';
import type { components } from '@/lib/api/schema';
import { failure, groupsApi, konferenca, poroka, skupno, signedIn } from '@/test/groupsApi';
import { renderApp } from '@/test/renderApp';

type Tag = components['schemas']['Tag'];

/** The groups stand-in plus the tags of group g-1 and the way a rename or delete is answered. */
function tagsApi(tags: Tag[], refuse?: ApiError) {
  const { api: groups, calls } = groupsApi([konferenca, poroka, skupno]);
  const list = tags.map((t) => ({ ...t }));
  const api: ApiClient = {
    ...groups,
    request: (async (method: string, path: string, body?: { name: string }) => {
      const one = /^\/groups\/g-[13]\/tags\/(.+)$/.exec(path);
      if (path.startsWith('/groups/g-1/tags') || path.startsWith('/groups/g-3/tags')) {
        calls.push(`${method} ${path} ${body ? JSON.stringify(body) : ''}`.trim());
      }
      if (path.endsWith('/tags')) return list.map((t) => ({ ...t }));
      if (one && refuse) throw refuse;
      if (one && method === 'PATCH') {
        const tag = list.find((t) => t.id === one[1]);
        if (tag && body) tag.name = body.name;
        return tag;
      }
      if (one && method === 'DELETE') {
        list.splice(
          list.findIndex((t) => t.id === one[1]),
          1,
        );
        return undefined;
      }
      return groups.request(method, path, body);
    }) as ApiClient['request'],
  };
  return { api, calls };
}

const old: Tag = { id: 't-1', name: 'udelezenec2205', contactCount: 3 };

describe('Manage tags (R-007-01, R-007-05, R-007-07)', () => {
  it('lists the tags with their contact counts and gives an Owner rename and delete', async () => {
    const { api } = tagsApi([old, { id: 't-2', name: 'gost', contactCount: 1 }]);
    renderApp('/groups/g-1/tags', { auth: signedIn(), api });
    const row = await screen.findByRole('row', { name: /udelezenec2205/ });
    expect(within(row).getByText('3')).toBeInTheDocument();
    expect(within(row).getByRole('button', { name: 'Rename' })).toBeInTheDocument();
    expect(within(row).getByRole('button', { name: 'Delete' })).toBeInTheDocument();
    expect(screen.getByRole('link', { name: 'Tags' })).toBeInTheDocument();
  });

  it('shows a Viewer neither the Tags tab nor a control', async () => {
    const { api } = tagsApi([old]);
    renderApp('/groups/g-3/tags', { auth: signedIn(), api });
    await screen.findByRole('row', { name: /udelezenec2205/ });
    expect(screen.queryByRole('link', { name: 'Tags' })).not.toBeInTheDocument();
    expect(screen.queryByRole('button', { name: 'Rename' })).not.toBeInTheDocument();
    expect(screen.queryByRole('button', { name: 'Delete' })).not.toBeInTheDocument();
  });

  it('renames a tag and shows the new name', async () => {
    const { api, calls } = tagsApi([old]);
    renderApp('/groups/g-1/tags', { auth: signedIn(), api });
    await userEvent.click(await screen.findByRole('button', { name: 'Rename' }));
    const dialog = screen.getByRole('dialog');
    const field = within(dialog).getByLabelText(/Tag name/);
    await userEvent.clear(field);
    await userEvent.type(field, 'udelezenec2025');
    await userEvent.click(within(dialog).getByRole('button', { name: 'Rename' }));
    expect(await screen.findByRole('row', { name: /udelezenec2025/ })).toBeInTheDocument();
    expect(calls).toContain('PATCH /groups/g-1/tags/t-1 {"name":"udelezenec2025"}');
    expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  });

  it('keeps the dialog and the typed name when the name is taken (UI-13)', async () => {
    const { api } = tagsApi([old], failure(409, 'TAG_NAME_TAKEN'));
    renderApp('/groups/g-1/tags', { auth: signedIn(), api });
    await userEvent.click(await screen.findByRole('button', { name: 'Rename' }));
    const dialog = screen.getByRole('dialog');
    const field = within(dialog).getByLabelText(/Tag name/);
    await userEvent.clear(field);
    await userEvent.type(field, 'GOST');
    await userEvent.click(within(dialog).getByRole('button', { name: 'Rename' }));
    expect(await within(dialog).findByText('A tag with this name already exists.')).toBeInTheDocument();
    expect(field).toHaveValue('GOST');
  });

  it('shows the reason for a name with a space', async () => {
    const problem = new ApiError(400, {
      status: 400,
      code: 'VALIDATION_FAILED',
      message: 'x',
      errors: [{ field: 'name', code: 'INVALID_CHARACTERS', message: 'x' }],
    });
    const { api } = tagsApi([old], problem);
    renderApp('/groups/g-1/tags', { auth: signedIn(), api });
    await userEvent.click(await screen.findByRole('button', { name: 'Rename' }));
    const dialog = screen.getByRole('dialog');
    await userEvent.type(within(dialog).getByLabelText(/Tag name/), ' x');
    await userEvent.click(within(dialog).getByRole('button', { name: 'Rename' }));
    expect(await within(dialog).findByText('Tag names use letters, digits, - and _.')).toBeInTheDocument();
  });

  it('deletes only after the second click and lists no tag afterwards', async () => {
    const { api, calls } = tagsApi([old]);
    renderApp('/groups/g-1/tags', { auth: signedIn(), api });
    await userEvent.click(await screen.findByRole('button', { name: 'Delete' }));
    expect(calls.some((c) => c.startsWith('DELETE'))).toBe(false);
    const dialog = screen.getByRole('dialog');
    expect(
      within(dialog).getByText('The tag is removed from its contacts. The contacts stay.'),
    ).toBeInTheDocument();
    await userEvent.click(within(dialog).getByRole('button', { name: 'Delete tag' }));
    expect(await screen.findByText(/No tags yet/)).toBeInTheDocument();
    expect(calls).toContain('DELETE /groups/g-1/tags/t-1');
  });
});

